<?php
declare(strict_types=1);
require_once __DIR__.'/../app/bootstrap.php';headers_secure();
try{if(!installed())fail('Document introuvable.',404);$id=str_limit($_GET['id']??'',36);$file=query('SELECT name,mime FROM files WHERE id=?',[$id])->fetch();if(!$file||$file['mime']!=='application/pdf'||(!admin()&&!file_public($id)))fail('Document introuvable.',404);}
catch(AppError $e){http_response_code($e->status);echo htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8');exit;}
catch(Throwable){http_response_code(500);echo 'Document indisponible.';exit;}
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=htmlspecialchars($file['name'],ENT_QUOTES,'UTF-8')?></title><link rel="stylesheet" href="pdf-viewer.css"></head><body data-file="<?=htmlspecialchars($id,ENT_QUOTES,'UTF-8')?>"><header class="pdf-toolbar"><button id="previous" aria-label="Page précédente">←</button><label>Page <input id="page-number" type="number" min="1" value="1" aria-label="Numéro de page"></label><span id="page-count">/ …</span><button id="next" aria-label="Page suivante">→</button><span class="pdf-spacer"></span><button id="zoom-out" aria-label="Réduire">−</button><button id="zoom-in" aria-label="Agrandir">+</button><a href="media.php?id=<?=rawurlencode($id)?>&download=1" aria-label="Télécharger le PDF">↓</a></header><p id="pdf-status" role="status">Ouverture du document…</p><main id="pdf-container"><div id="pdf-page"><canvas id="pdf-canvas" aria-label="Page du document PDF"></canvas><div id="pdf-text" class="textLayer"></div></div></main><script type="module" src="pdf-viewer.js"></script></body></html>
